const integer=(value,min,max,name)=>{if(!/^\d+$/.test(String(value)))throw new Error(`${name} must be an integer`);const n=Number(value);if(!Number.isSafeInteger(n)||n<min||n>max)throw new Error(`${name} must be within ${min}～${max} range`);return n;};
const decimal=(value,min,max,name)=>{if(String(value).trim()==='')throw new Error(`${name} cannot be empty`);const n=Number(value);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`${name} must be within ${min}～${max} range`);return n;};
const ipString=n=>[24,16,8,0].map(s=>(n>>>s)&255).join('.');
export function subnet(ip,prefix){const parts=String(ip).split('.');if(parts.length!==4)throw new Error('Enter a four-part IPv4 address, such as 192.168.10.130');const octets=parts.map(p=>integer(p,0,255,'Address octet'));const p=integer(prefix,0,32,'Prefix length');const n=octets.reduce((a,v)=>a*256+v,0)>>>0,mask=p===0?0:(0xffffffff<<(32-p))>>>0,network=(n&mask)>>>0,end=(network|(~mask>>>0))>>>0,total=2**(32-p);const standard=p<31;return{prefix:p,mask:ipString(mask),network:ipString(network),broadcast:standard?ipString(end):'No conventional broadcast address',first:ipString(standard?network+1:network),last:ipString(standard?end-1:end),total,usable:standard?total-2:total,binary:octets.map(v=>v.toString(2).padStart(8,'0')).join('.'),note:p===31?'/31 is treated as point-to-point; both addresses can identify endpoints.':p===32?'/32 represents one host address.':'Conventional broadcast subnet: exclude network and broadcast addresses.'};}
export function tcpAck(seq,payload,syn=false,fin=false){const n=integer(seq,0,4294967295,'Sequence number'),bytes=integer(payload,0,4294967295,'Data byte count');const used=bytes+Number(syn)+Number(fin);return{ack:(n+used)%4294967296,used,formula:`(${n} + ${bytes} + ${Number(syn)} + ${Number(fin)}) mod 2³²`,note:'Assumes contiguous reception with no gaps; does not simulate reordering, SACK or retransmission.'};}
export function delays(bytes,mbps,km,velocity){const b=integer(bytes,1,1e12,'Packet byte count'),rate=decimal(mbps,.000001,1e9,'Link rate'),distance=decimal(km,0,1e9,'Distance'),v=decimal(velocity,1,3e8,'Propagation speed');const transmission=b*8/(rate*1e6)*1000,propagation=distance*1000/v*1000,bdp=rate*1e6*(2*propagation/1000)/8;return{transmission,propagation,total:transmission+propagation,bdp,note:'One link, ignoring queuing and processing. BDP uses propagation-only RTT=2×one-way propagation delay.'};}
export function mss(mtu,ipVersion,tcpHeader){const m=integer(mtu,68,1000000,'MTU'),header=integer(tcpHeader,20,60,'TCP header length');if(header%4)throw new Error('TCP header length must be a multiple of 4 bytes');if(!['4','6'].includes(String(ipVersion)))throw new Error('IP version must be 4 or 6');const ip=String(ipVersion)==='6'?40:20;if(m<=ip+header)throw new Error('MTU must exceed the combined IP and TCP headers');return{ipHeader:ip,tcpHeader:header,mss:m-ip-header,note:'Simplified without IP options/extensions or tunnel overhead. Real limits depend on path MTU and negotiation.'};}
export function fragment(payload,mtu,header=20){const h=integer(header,20,60,'IPv4 header length');if(h%4)throw new Error('IPv4 header length must be a multiple of 4 bytes');const b=integer(payload,1,65535-h,'Original IP payload'),m=integer(mtu,h+8,65535,'MTU');const chunk=Math.floor((m-h)/8)*8,result=[];let offset=0;while(offset<b){const remaining=b-offset,size=remaining<=m-h?remaining:chunk;result.push({number:result.length+1,payload:size,total:size+h,offset:offset/8,mf:offset+size<b?1:0});offset+=size;}return result;}
